#define HEVT_REC_FLAGS_SYNC_EDGE_Pos 7u
#define HEVT_REC_FLAGS_SYNC_EDGE_Msk 0x00000080u
#define HEVT_REC_FLAGS_LAST_BEFORE_DISARM_Pos 8u
#define HEVT_REC_FLAGS_LAST_BEFORE_DISARM_Msk 0x00000100u
#define HEVT_REC_FLAGS_CHAIN_EN_Pos 16u
#define HEVT_REC_FLAGS_CHAIN_EN_Msk 0x00FF0000u
#define HEVT_REC_FLAGS_HTR_TRANS_COUNT_Pos 24u
#define HEVT_REC_FLAGS_HTR_TRANS_COUNT_Msk 0xFF000000u
#define HEVT_REC_DIAG_CNT_SAT_Pos 0u
#define HEVT_REC_DIAG_CNT_SAT_Msk 0x00000001u
#define HEVT_REC_DIAG_STUCK_Pos 1u
#define HEVT_REC_DIAG_STUCK_Msk 0x00000002u
#define HEVT_REC_DIAG_ORPHAN_Pos 2u
#define HEVT_REC_DIAG_ORPHAN_Msk 0x00000004u
#define HEVT_REC_DIAG_BUSY_AT_END_Pos 3u
#define HEVT_REC_DIAG_BUSY_AT_END_Msk 0x00000008u
#define HEVT_REC_DIAG_DISABLED_Pos 4u
#define HEVT_REC_DIAG_DISABLED_Msk 0x00000010u
#define HEVT_REC_DIAG_ORPHAN_COUNT_Pos 8u
#define HEVT_REC_DIAG_ORPHAN_COUNT_Msk 0x0000FF00u

typedef struct {
    uint32_t alpha;      /* events classified alpha */
    uint32_t beta;       /* events in the beta window */
    uint32_t reject;     /* ULD without ALPHA */
    uint32_t live_ticks; /* shared by alpha, beta and reject */
    uint32_t diag;       /* HEVT_REC_DIAG_* */
} hevt_floor_lane_t;

typedef struct {
    uint32_t count;      /* LLD without ULD */
    uint32_t reject;     /* ULD */
    uint32_t live_ticks;
    uint32_t diag;       /* HEVT_REC_DIAG_* */
} hevt_ref_lane_t;

/* Byte-exact image of the record on a little-endian MCU: read HEVT_REC_BYTES bytes into it. */
typedef struct {
    uint32_t hdr;            /* HEVT_REC_HDR_VALUE */
    uint32_t seq;
    uint32_t start_tick_lo;
    uint32_t start_tick_hi;
    uint32_t gate_ticks;
    uint32_t flags;          /* HEVT_REC_FLAGS_* */
    uint32_t htr_on_ticks;
    uint32_t pulser_count;
    uint32_t cfg_crc;
    uint32_t lost_total;
    hevt_floor_lane_t floor[HEVT_N_FLOOR];
    hevt_ref_lane_t ref[HEVT_N_REF];
    uint32_t reserved;
    uint32_t checksum;       /* sum of the 47 preceding words mod 2^32 */
} hevt_gate_record_t;

typedef char hevt_gate_record_size_check[(sizeof(hevt_gate_record_t) == HEVT_REC_BYTES) ? 1 : -1];

#endif /* HEAD_EVT_REGS_H */
